// Insert documents
db.orders.insertMany([
  {
    customerId: ObjectId("64a7b2c3d4e5f6a7b8c9d0e1"),
    items: [
      { productId: "SKU-001", name: "Laptop", quantity: 1, price: 999.99 },
      { productId: "SKU-042", name: "Mouse", quantity: 2, price: 29.99 }
    ],
    status: "pending",
    totalAmount: 1059.97,
    createdAt: new Date(),
    shippingAddress: {
      street: "123 Main St",
      city: "Seattle",
      state: "WA",
      zip: "98101"
    }
  }
]);

// Query with filters and projection
db.orders.find(
  {
    status: "pending",
    totalAmount: { $gte: 100 },
    "shippingAddress.state": "WA"
  },
  {
    customerId: 1,
    totalAmount: 1,
    status: 1,
    _id: 0
  }
).sort({ createdAt: -1 }).limit(10);

// Update with operators
db.orders.updateOne(
  { _id: ObjectId("64a7b2c3d4e5f6a7b8c9d0e1") },
  {
    $set: { status: "shipped", shippedAt: new Date() },
    $push: {
      statusHistory: {
        status: "shipped",
        timestamp: new Date(),
        updatedBy: "system"
      }
    }
  }
);

// Delete with filter
db.orders.deleteMany({
  status: "cancelled",
  createdAt: { $lt: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) }
});

// Revenue analysis by product category
db.orders.aggregate([
  { $match: { status: "completed", createdAt: { $gte: ISODate("2024-01-01") } } },
  { $unwind: "$items" },
  {
    $lookup: {
      from: "products",
      localField: "items.productId",
      foreignField: "sku",
      as: "productDetails"
    }
  },
  { $unwind: "$productDetails" },
  {
    $group: {
      _id: "$productDetails.category",
      totalRevenue: { $sum: { $multiply: ["$items.price", "$items.quantity"] } },
      orderCount: { $sum: 1 },
      avgOrderValue: { $avg: { $multiply: ["$items.price", "$items.quantity"] } }
    }
  },
  { $sort: { totalRevenue: -1 } },
  {
    $project: {
      category: "$_id",
      totalRevenue: { $round: ["$totalRevenue", 2] },
      orderCount: 1,
      avgOrderValue: { $round: ["$avgOrderValue", 2] },
      _id: 0
    }
  }
]);

// Compound index for common query patterns
db.orders.createIndex(
  { customerId: 1, status: 1, createdAt: -1 },
  { name: "customer_status_date_idx" }
);

// Partial index for active orders only
db.orders.createIndex(
  { createdAt: -1 },
  {
    partialFilterExpression: { status: { $in: ["pending", "processing"] } },
    name: "active_orders_idx"
  }
);

// TTL index for automatic document expiration
db.sessions.createIndex(
  { lastAccessedAt: 1 },
  { expireAfterSeconds: 3600, name: "session_ttl_idx" }
);

// Text index for full-text search
db.products.createIndex(
  { name: "text", description: "text", tags: "text" },
  { weights: { name: 10, tags: 5, description: 1 } }
);

